const HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>VibeScope \u2014 Understand the token before the trade</title><meta name=\"description\" content=\"Independent read-only vibe/vibe testnet token inspector and transparent fee calculator.\"><style>\n:root{color-scheme:dark;--bg:#101513;--panel:#18201c;--muted:#a2b3a8;--lime:#c2f970;--line:#304237}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#edf5ee;font:16px/1.5 system-ui,sans-serif}header,main,footer{max-width:1180px;margin:auto;padding:25px 30px}header{display:flex;justify-content:space-between;border-bottom:1px solid var(--line)}a{color:var(--lime);text-decoration:none}a:hover{text-decoration:underline}.brand{font-size:24px;font-weight:800;letter-spacing:-1px}.brand span{color:var(--lime)}.tag{font:12px monospace;border:1px solid var(--line);padding:8px 12px;border-radius:30px;color:var(--muted)}.hero{padding:48px 0 30px;max-width:760px}.eyebrow{color:var(--lime);font:12px monospace;letter-spacing:2px}h1{font-size:clamp(36px,5vw,60px);line-height:1.08;letter-spacing:-2px;margin:18px 0}p{color:var(--muted)}.search{display:flex;gap:12px;background:var(--panel);padding:12px;border:1px solid var(--line);border-radius:15px}input{min-width:0;background:#101713;border:1px solid var(--line);border-radius:8px;color:white;padding:14px;font:inherit;width:100%}button{border:0;border-radius:8px;padding:14px 23px;font:600 15px system-ui;cursor:pointer;background:var(--lime);color:#183015;white-space:nowrap}button:hover{filter:brightness(1.08)}button:disabled{opacity:.5}.quiet{background:transparent;color:var(--muted);padding:8px 0;text-decoration:underline}.status{min-height:28px;margin:12px 0 24px;color:var(--muted);font-size:14px}.grid{display:grid;grid-template-columns:1.3fr 1fr;gap:20px}.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:27px;margin-bottom:20px}h2{font-size:22px;letter-spacing:-.5px;margin:0 0 8px}h3{font-size:14px;font-weight:500;color:var(--muted);margin:0}.tokenhead{display:flex;justify-content:space-between;gap:12px;margin-bottom:25px}.symbol{color:var(--lime);font:14px monospace}.badge{font:11px monospace;background:#273c29;color:var(--lime);padding:6px 10px;border-radius:6px;height:fit-content}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.value{font-size:26px;font-weight:600;letter-spacing:-1px;margin:6px 0 22px}.row{display:flex;justify-content:space-between;gap:15px;padding:11px 0;border-bottom:1px solid var(--line);font-size:14px}.row span:first-child{color:var(--muted)}.track{height:9px;background:#304237;border-radius:8px;overflow:hidden;margin:14px 0}.fill{height:100%;background:var(--lime)}.small{font-size:12px;color:var(--muted)}.mono{font-family:monospace;overflow-wrap:anywhere}.links{display:flex;gap:18px;margin-top:20px;flex-wrap:wrap}.calcresult{background:#101713;padding:20px;border-radius:10px;margin-top:18px}.calcresult strong{color:var(--lime);font-size:28px}.split{display:flex;height:12px;border-radius:8px;overflow:hidden;margin:22px 0}.split i{display:block}.empty{padding:50px 20px;text-align:center;border:1px dashed var(--line);border-radius:16px}.error{color:#ffb4a2}.note{border-left:2px solid var(--lime);padding-left:15px}label{display:block;color:var(--muted);font-size:13px;margin:20px 0 7px}footer{border-top:1px solid var(--line);color:var(--muted);font-size:12px;margin-top:30px;display:flex;justify-content:space-between;gap:20px}details{margin-top:18px}summary{cursor:pointer;color:var(--muted)}[hidden]{display:none!important}@media(max-width:750px){header,main,footer{padding:20px}.grid{grid-template-columns:1fr}.search{flex-direction:column}.hero{padding-top:30px}.stats{gap:10px}.value{font-size:22px}.tag{font-size:10px}.card{padding:20px}footer{display:block}}\n</style></head><body><header><div class=\"brand\">\u25c9 Vibe<span>Scope</span></div><div class=\"tag\">ROBINHOOD CHAIN \u00b7 TESTNET</div></header><main><section class=\"hero\"><div class=\"eyebrow\">READ THE MECHANICS</div><h1>Understand the token.<br>Before the trade.</h1><p>Inspect launch mechanics, follow the tax, and explore fee-only costs. No wallet connection. No signatures.</p></section><form id=\"search\" class=\"search\"><input id=\"address\" aria-label=\"Token address or vibe/vibe URL\" placeholder=\"Paste a token address or vibe/vibe token URL\" required autocomplete=\"off\"><button id=\"inspect\">Inspect token \u2197</button></form><button class=\"quiet\" id=\"example\">Try RKTOZ \u2014 a live testnet example</button><div id=\"status\" class=\"status\" role=\"status\" aria-live=\"polite\">Independent community tool \u00b7 Not affiliated with vibe/vibe or Robinhood.</div><div id=\"empty\" class=\"empty\"><div class=\"eyebrow\">ONE ADDRESS. A CLEARER PICTURE.</div><p>Launch details \u2192 Tax breakdown \u2192 Cost model</p><span class=\"small\">Data comes from the vibe/vibe app API. Test assets have no monetary value.</span></div><div id=\"result\" hidden><div class=\"grid\"><section><article class=\"card\"><div class=\"tokenhead\"><div><div id=\"symbol\" class=\"symbol\"></div><h2 id=\"name\"></h2></div><div id=\"generation\" class=\"badge\"></div></div><div class=\"stats\"><div><h3>Trade tax</h3><div id=\"tax\" class=\"value\"></div></div><div><h3>Paired with</h3><div id=\"pair\" class=\"value\"></div></div><div><h3>Stage</h3><div id=\"stage\" class=\"value\" style=\"font-size:20px\"></div></div></div><p id=\"description\"></p><div class=\"row\"><span>Reserve / target</span><span id=\"reserve\"></span></div><div class=\"track\"><div id=\"progress\" class=\"fill\"></div></div><div class=\"small\" id=\"progressText\"></div><div class=\"row\"><span>Wallet transfers</span><span id=\"transfers\"></span></div><div class=\"row\"><span>Token address</span><span id=\"tokenAddress\" class=\"mono\"></span></div><div class=\"links\"><a id=\"appLink\" target=\"_blank\" rel=\"noopener\">Open in vibe/vibe \u2197</a><a id=\"explorer\" target=\"_blank\" rel=\"noopener\">Explorer \u2197</a></div></article><article class=\"card\"><h2>Where the tax goes</h2><p class=\"small\">Shares of the collected tax, not shares of the trade amount.</p><div class=\"split\" id=\"split\"></div><div id=\"weights\"></div><p class=\"small\" id=\"weightNote\"></p></article></section><aside><article class=\"card\"><div class=\"eyebrow\">FEE-ONLY SCENARIO</div><h2 style=\"margin-top:10px\">The cost of a round trip</h2><p class=\"small\">A simplified model at an unchanged market price. This is not a trade quote.</p><label for=\"amount\">Hypothetical amount (ETH equivalent)</label><input type=\"number\" id=\"amount\" value=\"0.01\" min=\"0\" step=\"any\"><div class=\"calcresult\"><h3>Remaining after modeled buy + sell taxes</h3><strong id=\"remaining\"></strong><div class=\"small\" id=\"loss\"></div></div><div class=\"row\"><span>Modeled tax drag</span><span id=\"drag\"></span></div><div class=\"row\"><span>Price rise to offset taxes</span><span id=\"breakeven\"></span></div><p class=\"small note\">Uses tax-inclusive buy principal \u00f7 (1 + rate), then sell proceeds \u00d7 (1 \u2212 rate). Excludes gas, curve movement, slippage, pool fees, opening tax and any extra tax on a paired token. Break-even is a model, not a return forecast.</p></article><article class=\"card\"><h2>Evidence, not a score</h2><div id=\"fresh\" class=\"small\"></div><p class=\"small\">API-reported data is not an independent contract audit. A token's name, description and links are creator supplied. Missing data stays unavailable.</p><details><summary>Source & methodology</summary><p class=\"small\" id=\"source\"></p><a class=\"small\" href=\"https://testnet.vibevibe.fun/docs/protocol\" target=\"_blank\" rel=\"noopener\">Protocol reference \u2197</a></details></article></aside></div></div></main><footer><span>VibeScope \u00b7 Built by bars26 \u00b7 v0.1</span><span>Read-only \u00b7 No wallet access \u00b7 Testnet only</span></footer><script type=\"module\" src=\"/app.js\"></script></body></html>\n";const JS="const $=id=>document.getElementById(id);let current=null;let seq=0;\nconst fmt=(n,d=6)=>Number.isFinite(n)?n.toLocaleString('en-US',{maximumFractionDigits:d}):'Unavailable';\nconst text=(id,v)=>$(id).textContent=v;\nexport function parseAddress(v){const raw=v.trim();if(/^0x[a-fA-F0-9]{40}$/.test(raw))return raw.toLowerCase();try{const u=new URL(raw);if(u.hostname!=='testnet.vibevibe.fun'||u.protocol!=='https:')return null;return /^\\/(?:token|token-v6|t)\\/(0x[a-fA-F0-9]{40})\\/?$/.exec(u.pathname)?.[1].toLowerCase()||null}catch{return null}}\nexport function model(amount,rate){const remaining=amount/(1+rate)*(1-rate);return{remaining,loss:amount-remaining,drag:1-(1-rate)/(1+rate),breakeven:(1+rate)/(1-rate)-1}}\nfunction calc(){const a=Number($('amount').value),r=current?.taxBps/10000;if(!Number.isFinite(a)||a<0||!Number.isFinite(r)||r>=1){for(const id of ['remaining','loss','drag','breakeven'])text(id,'Unavailable');return}const m=model(a,r);text('remaining',fmt(m.remaining,8)+' ETH');text('loss',fmt(m.loss,8)+' ETH modeled cost');text('drag',fmt(m.drag*100,3)+'%');text('breakeven','+'+fmt(m.breakeven*100,3)+'%')}\nasync function inspect(v){const address=parseAddress(v),ticket=++seq;if(!address){text('status','Enter a valid 0x token address or an HTTPS testnet.vibevibe.fun token URL.');$('status').classList.add('error');return}current=null;$('result').hidden=true;$('empty').hidden=true;$('inspect').disabled=true;$('status').classList.remove('error');text('status','Reading public launch data\u2026');try{const res=await fetch('/api/token/'+address);const body=await res.json();if(ticket!==seq)return;if(!res.ok)throw new Error(body.error||'Source unavailable. Please try again.');const l=body.launch;current=l;text('name',l.name||'Unnamed token');text('symbol','$'+(l.symbol||'?'));text('generation',body.generation);text('tax',Number.isFinite(l.taxBps)?fmt(l.taxBps/100,2)+'%':'Unavailable');text('pair',l.pairSymbol|| (l.pairIsNative?'ETH':'Unavailable'));text('stage',l.graduated?'Graduated':l.lifecycle==='CURVE_TRADING'?'On curve':l.lifecycle||'Unavailable');text('description',l.content?.description||'No project description supplied.');text('tokenAddress',address.slice(0,8)+'\u2026'+address.slice(-6));$('appLink').href='https://testnet.vibevibe.fun/token/'+address;$('explorer').href='https://explorer.testnet.chain.robinhood.com/address/'+address;\nconst reserve=l.curve?.pairReserveUnits,target=l.targetPairUnits;let pct=null;if(reserve!=null&&target!=null&&BigInt(target)>0n){pct=Number(BigInt(reserve)*10000n/BigInt(target))/100;text('reserve',fmt(Number(reserve)/1e18,4)+' / '+fmt(Number(target)/1e18,4)+' '+(l.pairSymbol||'pair units'));text('progressText',fmt(pct,2)+'% of reserve target \u00b7 not a price forecast');if(!l.pairIsNative){text('reserve','See source for pair units');text('progressText',fmt(pct,2)+'% of reserve target \u00b7 raw unit ratio')}}else{text('reserve','Unavailable');text('progressText','Reserve progress unavailable')}$('progress').style.width=Math.max(0,Math.min(100,pct||0))+'%';text('transfers',l.curve?.transfersUnlocked===true?'Unlocked':l.curve?.transfersUnlocked===false?'Locked':'Unavailable');\n$('weights').replaceChildren();$('split').replaceChildren();const entries=[['Platform',20,'#c2f970']];if(body.generation==='V6'&&l.weights){for(const [key,label,color]of[['cashBps','Project treasury','#72c8a5'],['holdersPairBps','Holders \u00b7 pair asset','#6d9cd6'],['holdersBps','Holders \u00b7 project token','#b49be1'],['burnBps','Burn','#ebaa76']]){const n=l.weights[key];if(typeof n==='number')entries.push([label,n/10000*80,color])}text('weightNote','V6: platform keeps one fifth; creator weights divide the remaining four fifths. Token rewards are claimable after graduation.')}else{entries.length=0;text('weightNote','Legacy tax routing is not modeled in this version. Verify on the token page.')}\nfor(const[label,p,color]of entries){const row=document.createElement('div');row.className='row';const a=document.createElement('span'),b=document.createElement('span');a.textContent=label;b.textContent=fmt(p,3)+'% of tax';b.style.color=color;row.append(a,b);$('weights').append(row);const bar=document.createElement('i');bar.style.width=p+'%';bar.style.background=color;$('split').append(bar)}const f=body.freshness;text('fresh',f?('API freshness: '+f.status+' \u00b7 source '+f.source+'\\nObserved '+f.observedAt+'\\nAs-of block '+f.asOfBlock+(f.coverageComplete===false?' \u00b7 incomplete coverage':'')):'Freshness evidence unavailable');text('source',body.source+' \u00b7 Retrieved '+body.fetchedAt);text('status','Loaded public '+body.generation+' launch data \u00b7 '+new Date(body.fetchedAt).toLocaleTimeString());$('result').hidden=false;calc();history.replaceState(null,'','?token='+address)}catch(e){if(ticket!==seq)return;current=null;$('empty').hidden=false;text('status',e.message);$('status').classList.add('error')}finally{if(ticket===seq)$('inspect').disabled=false}}\n$('search').addEventListener('submit',e=>{e.preventDefault();inspect($('address').value)});$('example').onclick=()=>{$('address').value='0x91B3D0A5EE829A4116432Ed4B6eC1ae27d53696C';inspect($('address').value)};$('amount').oninput=calc;const initial=new URLSearchParams(location.search).get('token');if(initial){$('address').value=initial;inspect(initial)}\n";
const BASE='https://testnet.vibevibe.fun/api/v1/chains/46630';
const response=(body,status=200)=>new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json','cache-control':'no-store'}});
export default {async fetch(request){const url=new URL(request.url);if(request.method!=='GET')return response({error:'Read-only endpoint'},405);if(url.pathname==='/app.js')return new Response(JS,{headers:{'content-type':'text/javascript'}});if(url.pathname==='/')return new Response(HTML,{headers:{'content-type':'text/html; charset=utf-8','content-security-policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self'; frame-ancestors 'none'",'x-content-type-options':'nosniff','referrer-policy':'no-referrer'}});
const match=/^\/api\/token\/(0x[a-fA-F0-9]{40})$/.exec(url.pathname);if(!match)return response({error:'Not found'},404);let source='',generation='V6';try{let endpoint=BASE+'/v6/launches/'+match[1];let upstream=await fetch(endpoint,{headers:{accept:'application/json'},signal:AbortSignal.timeout(15000)});if(upstream.status===404){generation='Legacy';endpoint=BASE+'/launches/'+match[1];upstream=await fetch(endpoint,{headers:{accept:'application/json'},signal:AbortSignal.timeout(15000)})}if(!upstream.ok)return response({error:upstream.status===404?'Token not found in the supported testnet sources.':'The upstream data source is unavailable ('+upstream.status+').'},upstream.status===404?404:502);const body=await upstream.json();const l=body.data?.launch;if(!l||l.tokenAddress?.toLowerCase()!==match[1].toLowerCase())return response({error:'Source returned an unsupported launch format. No values were inferred.'},502);source=endpoint;return response({launch:l,generation,freshness:body.meta?.freshness||null,source,fetchedAt:new Date().toISOString()})}catch{return response({error:'Data source timed out or could not be read. Try again later.'},502)}}};
